async function syncPlayersForGame(db, apiKey, team, playhqGameId) {
  const summary = await playhq(`/games/${playhqGameId}/summary`, apiKey, "v2");
  const appearances = summary.data?.appearances || [];
  const ourTeamAppearances = appearances.filter((a) => a.teamId === team.playhq_team_id);
  for (const p of ourTeamAppearances) {
    await db.prepare(
      `INSERT OR IGNORE INTO team_sheet_players
         (game_id, playhq_player_id, first_name, last_name, player_number, player_position, captain_role, is_fill_in, is_emergency, role_type)
         VALUES (?,?,?,?,?,?,?,?,?,?)`
    ).bind(
      playhqGameId,
      p.id,
      p.firstName,
      p.lastName,
      p.playerNumber,
      p.position || null,
      p.captainRole || null,
      p.isFillIn ? 1 : 0,
      p.isEmergency ? 1 : 0,
      p.roleType || "Player"
    ).run();
  }
  const { results: players } = await db.prepare(`SELECT playhq_player_id, first_name, last_name FROM team_sheet_players WHERE game_id = ? AND role_type = 'Player'`).bind(playhqGameId).all();
  return players;
}
