async function populateWheel(db, team, gameId, gradeName, players) {
  const count = players.length;
  if (count < 20 || count > 22) {
    console.warn(`[wheel] ${gradeName}: unexpected squad size ${count} for game ${gameId}`);
  }
  for (const p of players) {
    await db.prepare(`INSERT OR IGNORE INTO wheel_players (team_id, game_id, playhq_player_id, player_name) VALUES (?,?,?,?)`).bind(team.id, gameId, p.playhq_player_id, `${p.first_name} ${p.last_name}`).run();
  }
  await db.prepare(
    `INSERT INTO wheel_state (team_id, game_id, grade_name, player_count, synced_at, is_test)
       VALUES (?,?,?,?,?,0)
       ON CONFLICT(team_id) DO UPDATE SET
         game_id = excluded.game_id, grade_name = excluded.grade_name,
         player_count = excluded.player_count, synced_at = excluded.synced_at, is_test = 0`
  ).bind(team.id, gameId, gradeName, count, (/* @__PURE__ */ new Date()).toISOString()).run();
}
