async function runSync(env) {
  const db = env.DB;
  const teams = await currentTeams(db);
  const results = [];
  for (const team of teams) {
    try {
      await syncFixturesForTeam(db, env.PLAYHQ_API_KEY, team);
      const fixture = await nextEligibleFixture(db, team.id);
      if (!fixture) {
        await db.prepare(`DELETE FROM wheel_state WHERE team_id = ?`).bind(team.id).run();
        results.push({ team: team.team_name, status: "no_eligible_fixture" });
        continue;
      }
      const players = await syncPlayersForGame(db, env.PLAYHQ_API_KEY, team, fixture.playhq_game_id);
      await populateWheel(db, team, fixture.playhq_game_id, gradeLabel(team), players);
      results.push({ team: team.team_name, status: "synced", gameId: fixture.playhq_game_id, playerCount: players.length });
    } catch (e) {
      results.push({ team: team.team_name, status: "error", error: e.message });
    }
  }
  return results;
}
